"""Recommendation model generated by the AI module."""

from sqlalchemy import ForeignKey, String
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.core.database import Base
from app.models.base import TimestampMixin, UTCDateTime, generate_uuid


class Recommendation(TimestampMixin, Base):
    """A personalized, explainable recommendation for a worker.

    Never medical advice — operational suggestions based on model context.
    Status: pending | accepted | dismissed | completed
    """

    __tablename__ = "recommendations"

    id: Mapped[str] = mapped_column(String, primary_key=True, default=generate_uuid)
    user_id: Mapped[str] = mapped_column(
        String, ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True
    )
    session_id: Mapped[str | None] = mapped_column(
        String, ForeignKey("work_sessions.id", ondelete="SET NULL"), nullable=True, index=True
    )
    generated_at: Mapped[str] = mapped_column(UTCDateTime(timezone=True), nullable=False, index=True)
    category: Mapped[str] = mapped_column(String(50), nullable=False)
    # break | task_management | schedule | workload | general
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    body: Mapped[str] = mapped_column(String(2000), nullable=False)
    reason: Mapped[str | None] = mapped_column(String(2000), nullable=True)
    status: Mapped[str] = mapped_column(String(20), nullable=False, default="pending")
    priority: Mapped[str] = mapped_column(String(20), nullable=False, default="normal")
    # low | normal | high

    user: Mapped["User"] = relationship("User", back_populates="recommendations")


# Resolve forward reference
from app.models.user import User  # noqa: E402
